import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);
        String[] aLine = br.readLine().split(" ");
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(aLine[i]);
        }

        int midpoint = n / 2;
        List<Integer> part1 = new ArrayList<>();
        List<Integer> part2 = new ArrayList<>();

        buildPart1(0, 0, a, m, midpoint, part1);
        buildPart2(midpoint, 0, a, m, n, part2);

        Set<Integer> uniquePart1Set = new HashSet<>(part1);
        List<Integer> uniquePart1 = new ArrayList<>(uniquePart1Set);
        Collections.sort(uniquePart1);

        int bestSum = 0;
        for (int val : part2) {
            int index = Collections.binarySearch(uniquePart1, m - val);
            if (index < 0) {
                index = -index - 1;
            }
            if (index > 0) {
                int candidateSum = uniquePart1.get(index - 1) + val;
                if (candidateSum > bestSum) {
                    bestSum = candidateSum;
                }
            }
        }
        System.out.println(bestSum);
    }

    private static void buildPart1(int i, int total, int[] a, int m, int midpoint, List<Integer> part1) {
        if (i == midpoint) {
            part1.add(total);
        } else {
            buildPart1(i + 1, (total + a[i]) % m, a, m, midpoint, part1);
            buildPart1(i + 1, total, a, m, midpoint, part1);
        }
    }

    private static void buildPart2(int i, int total, int[] a, int m, int n, List<Integer> part2) {
        if (i == n) {
            part2.add(total);
        } else {
            buildPart2(i + 1, (total + a[i]) % m, a, m, n, part2);
            buildPart2(i + 1, total, a, m, n, part2);
        }
    }
}
